exercises.solution:
public class Item {
    private String name;
    private int qty;

    public Item(String name, int qty) {
        this.name = name;
        this.qty = qty;
    }

    public void take(int n) { qty = Math.max(0, qty - n); }

    public String toString() { return name + " x " + qty; }
}
